#ifndef DIODELADDER_H_
#define DIODELADDER_H_

#include <stdint.h>

/* Electrical constants (S092 P6 §3; the SPICE runs' 27 C thermal voltage). */
#define DL_FS          44108.0f
#define DL_VT          0.02585f
#define DL_2VT         (2.0f * DL_VT)
#define DL_C18         18e-9f          /* bottom ladder capacitor */
#define DL_C19         33e-9f          /* C19 = C24 = C26 */
/* Output level: int16 full scale = 3 V at OTA pin 6 (the accent peaks of the
 * P4 run reach about 1.7 V, so about 5 dB of headroom). */
#define DL_OUT_SCALE   (32767.0f / 3.0f)

/*
 * One Resonance point of the real-time network (S092 P6 §5.3), generated.
 *
 * What:       the slow block system in the physical capacitor basis:
 *             z' = phi z + gam_rows0..7 . w_mean (8 states), plus the two
 *             asymptote copies (rows 8, 9 of gam, decay ALK_NET_ASYM_DECAY);
 *             slow outputs r = cs . z - (z8, z9). The fast modes (unit input
 *             gain from tp_pre, trapezoidal one-poles alf, bef), their output
 *             gains cf, the asymptote gains ga and the instantaneous gains d.
 *             Rows/first index: 0 = u (into Q12), 1 = v (OTA input).
 *             Columns of gam, ga, d: 0 = tp_pre, 1 = s.
 * Why:        every entry depends on Resonance only and varies smoothly with
 *             it (physical basis; normalised fast modes), so linear
 *             interpolation between points is valid (S092 P6 §5.3 table).
 * Layout:     116 floats (464 B) per point.
 */
typedef struct {
	float phi[8][8];
	float gam[10][2];
	float cs[2][8];
	float alf[2];
	float bef[2];
	float cf[2][2];
	float ga[2][2];
	float d[2][2];
} DiodeLadderNet;

/*
 * Ladder, network and OTA state of one voice (S093 P0).
 *
 * What:       x0..x3 the four ladder capacitor voltages / 2 Vt; t0..t3, tin,
 *             tout, tota the secant gains of the previous sample (rungs,
 *             input pair, Q21, OTA); zo the C27/C25 coupling state (V);
 *             y0, y1 the fast modes; qu, qv the asymptote one-poles; z[10]
 *             the slow block system; rU/rV the slow outputs (this block's end
 *             and the previous); the previous sample's tp_pre, s, x_in, v_hp,
 *             OTA argument and I_abc; the ladder current and I_abc reached at
 *             the last block end; the per-block coefficient set (setNet).
 * Why:        S092 P0 §1.3: no state lives across a render outside the voice
 *             struct.
 * Layout:     about 70 floats (≈ 290 B) inside the voice's runtime slot.
 */
typedef struct {
	float x0, x1, x2, x3;
	float t0, t1, t2, t3, tin, tout, tota;
	float zo;
	float y0, y1, qu, qv;
	float z[10];
	float rU, rV, rUPrev, rVPrev;
	float tpLast, sLast, xinLast, vhpLast, vcaLast, iAbcLast;
	float iLad;          /* prewarped ladder current reached (A) */
	float iAbc;          /* OTA control current reached (A) */
	/* per-block coefficients (DiodeLadder_setNet) */
	const DiodeLadderNet *netLo;
	const DiodeLadderNet *netHi;
	float netFrac;
	float alf0, alf1, bef0, bef1;
	float cfu0, cfu1, cfv0, cfv1;
	float gau0, gau1, gav0;
	float ku0, ku1, dv0;
} DiodeLadder;

void DiodeLadder_init(DiodeLadder *dl);
void DiodeLadder_setNet(DiodeLadder *dl, const DiodeLadderNet *lo,
                        const DiodeLadderNet *hi, float frac);
void DiodeLadder_renderA(DiodeLadder *dl, int16_t *buf, float sScale,
                         float iLadEnd, float iAbcEnd);
void DiodeLadder_renderB(DiodeLadder *dl, int16_t *buf, float sScale,
                         float iLadEnd, float iAbcEnd);

#endif /* DIODELADDER_H_ */

